// Expo config plugin: build the APK for arm64-v8a only.
//
// Why: the target devices (modern phones + arm64 emulator) are all arm64-v8a,
// so compiling the other 3 ABIs only wastes build time and APK size.
// android/ is regenerated by `expo prebuild --clean`, so the flag has to be
// applied through a config plugin to survive regeneration.
//
// To support all ABIs again (e.g. Play Store release): delete this file,
// remove its entry from app.json plugins, then rebuild.
const { withAppBuildGradle, withGradleProperties } = require('@expo/config-plugins');

const VERSION_NAME_ANCHOR = /versionName\s+"[^"]*"/;
const ARM64_ONLY = 'arm64-v8a';
const RN_ARCHITECTURES_KEY = 'reactNativeArchitectures';

function withArm64Only(config) {
  config = withAppBuildGradle(config, (config) => {
    const contents = config.modResults.contents;
    // prebuild may run on an existing android/ dir — stay idempotent.
    if (contents.includes('abiFilters')) {
      return config;
    }
    if (!VERSION_NAME_ANCHOR.test(contents)) {
      throw new Error(
        '[withArm64Only] Could not find versionName in android/app/build.gradle, refusing to guess where abiFilters goes.'
      );
    }
    config.modResults.contents = contents.replace(
      VERSION_NAME_ANCHOR,
      (match) =>
        `${match}\n` +
        `        ndk {\n` +
        `            abiFilters 'arm64-v8a'\n` +
        `        }\n` +
        // NOTE: ndk.abiFilters alone does NOT restrict CMake builds
        // (verified: x86 objects were still compiled with only the ndk
        // block). CMake reads externalNativeBuild.cmake.abiFilters.
        `        externalNativeBuild {\n` +
        `            cmake {\n` +
        `                abiFilters 'arm64-v8a'\n` +
        `            }\n` +
        `        }`
    );
    return config;
  });

  // The React Native Gradle Plugin reads `reactNativeArchitectures` from
  // gradle.properties and forces THAT abi list for packaging (overriding the
  // ndk block above — verified: APK shipped all 4 ABIs with only the
  // build.gradle blocks set). This is the switch that actually trims the APK.
  config = withGradleProperties(config, (config) => {
    let found = false;
    config.modResults = config.modResults.map((item) => {
      if (item.key === RN_ARCHITECTURES_KEY) {
        found = true;
        return { ...item, value: ARM64_ONLY };
      }
      return item;
    });
    if (!found) {
      config.modResults.push({
        type: 'property',
        key: RN_ARCHITECTURES_KEY,
        value: ARM64_ONLY,
      });
    }
    return config;
  });

  return config;
}

module.exports = withArm64Only;
